import re,os,collections
root=os.getcwd()
def path(m): return os.path.join(root, m.replace('.','/')+".lean")
def imports(m):
    p=path(m)
    if not os.path.exists(p): return []
    return [mm.group(1) for line in open(p) for mm in [re.match(r'^import\s+(\S+)',line)] if mm and mm.group(1).startswith("AlgebraicJacobian")]
start="AlgebraicJacobian.Picard.Pic0SigmaSheaf"
# BFS with parent tracking
par={start:None}; q=collections.deque([start])
while q:
    m=q.popleft()
    for c in imports(m):
        if c not in par:
            par[c]=m; q.append(c)
for tgt in ["AlgebraicJacobian.Challenge"]:
    if tgt in par:
        ch=[]; c=tgt
        while c: ch.append(c); c=par[c]
        print(" CHAIN: "+"\n   <- ".join(ch))
EOF
